#include <iostream>
#include <bitset>
#include <cstdio>
#include <vector>
#include <algorithm>

#define C 300000

using namespace std;

int main() {
    int n, q;
    int c[300000];
    bitset<C + 1> has_c;

    scanf("%d %d", &n, &q);
    for (int i = 0; i < n; i++) {
        scanf("%d", &c[i]);
        has_c[c[i]] = true;
    }

    for (int i = 0; i < q; i++) {
        int query_i;
        scanf("%d", &query_i);
        int max_r = -1;

        // Start from the maximum possible r and find the first matching bit
        for (int r = min(query_i - 1, C); r >= 0; r--) {
            // Calculate the starting point for k
            int start = (C - r) / query_i;
            for (int k = start; k >= 0; k--) {
                if (has_c[k * query_i + r]) {
                    max_r = max(r, max_r);
                    break;
                }
            }
            if (max_r >= 0) {
                break;
            }
        }
        printf("%d\n", max_r);
    }

    return 0;
}

